import{_ as i,B as o,o as r,c as d,a8 as l,a as t,E as n,f as a}from"./chunks/framework.CNIpabDg.js";const y=JSON.parse(`{"title":"Debug (executable)","description":"How Xila's native Debug executable serves bounded diagnostics, screenshots and synthetic input over a VFS transport.","frontmatter":{"layout":"doc","docType":"explanation","description":"How Xila's native Debug executable serves bounded diagnostics, screenshots and synthetic input over a VFS transport."},"headers":[],"relativePath":"explanation/architecture/executables/debug.md","filePath":"explanation/architecture/executables/debug.md","lastUpdated":1793145952000}`),c={name:"explanation/architecture/executables/debug.md"};function p(u,e,h,g,b,m){const s=o("CodeReference");return r(),d("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[4]||(e[4]=l(`<h1 id="debug-executable" tabindex="-1">Debug (executable) <a class="header-anchor" href="#debug-executable" aria-label="Permalink to &quot;Debug (executable)&quot;">​</a></h1><p>The <code>debug</code> executable is a host-side diagnostics agent. It provides <strong>task/memory inspection, screen capture, a bounded LVGL UI tree and synthetic pointer/keyboard input</strong> through a character-device transport. The payload schema lives in the reusable <a href="/explanation/architecture/libraries/debug_protocol.html">Debug protocol library</a>; this executable owns the live service and its integration with the Graphics, Task, Memory and VFS subsystems.</p><h2 id="startup-and-runtime-ownership" tabindex="-1">Startup and runtime ownership <a class="header-anchor" href="#startup-and-runtime-ownership" aria-label="Permalink to &quot;Startup and runtime ownership&quot;">​</a></h2><p><code>DebugExecutable</code> implements <code>ExecutableTrait</code>. The normal invocation creates an informational graphics window; passing <code>--background</code> omits the window but still starts the service. It spawns a Task child called <code>Debug agent transport</code> and opens the VFS endpoint <code>/devices/debug/transport</code> with read/write access.</p><p>The foreground loop checks window events every <strong>50 ms</strong>. Closing the window signals the transport task to stop and then joins it. The transport itself polls its <strong>synchronous</strong> file interface; a busy read sleeps <strong>10 ms</strong> and retries. In background mode the foreground loop has no window-close event, so its lifetime depends on external task/runtime shutdown.</p><p>The executable <strong>does not create the transport device</strong>; a platform or test environment must mount it before requests can be served. Graphics access requires a functioning Graphics manager, even for headless UI inspection and injection.</p><h2 id="request-and-response-framing" tabindex="-1">Request and response framing <a class="header-anchor" href="#request-and-response-framing" aria-label="Permalink to &quot;Request and response framing&quot;">​</a></h2><p>The transport reads at most <code>MAX_REQUEST_BYTES + 1</code> bytes and rejects requests larger than <strong>16 KiB</strong>. It parses the JSON <code>Request</code> enum and applies <code>debug_protocol::validate_request</code>. Responses are JSON objects terminated by a newline:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;result&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;width&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">800</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;height&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">600</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>An error uses <code>{&quot;ok&quot;:false,&quot;error&quot;:{&quot;code&quot;:&quot;…&quot;,&quot;message&quot;:&quot;…&quot;}}</code>. Normal JSON responses are capped at <strong>64 KiB</strong>; oversized responses become a <code>response_too_large</code> error rather than being sent partially. A successful screenshot returns metadata in the JSON frame followed immediately by the raw <strong>RGBA8888</strong> byte payload, whose length is <code>payload_bytes</code>. Clients must read that extra binary frame before the next response.</p><h2 id="supported-operations-and-limits" tabindex="-1">Supported operations and limits <a class="header-anchor" href="#supported-operations-and-limits" aria-label="Permalink to &quot;Supported operations and limits&quot;">​</a></h2><ul><li><code>diagnostics</code>: memory total/used/free/page size and <strong>up to 64</strong> task records, with a truncation flag.</li><li><code>resolution</code> and <code>screenshot</code>: active display dimensions, or a bounded RGBA8888 screenshot with validated metadata.</li><li><code>ui_tree</code>: a bounded, potentially truncated snapshot. Element IDs are local to the snapshot and must not be treated as persistent object identifiers.</li><li><code>pointer_move</code>, <code>pointer_button</code>, <code>key</code> and <code>text</code>: synthetic input queued through Graphics; coordinates must fit the display and the internal signed-point representation.</li><li>Text input is restricted to <strong>printable ASCII</strong>. Key names include arrows, Enter, Escape, Backspace, Delete, Home, End, Next and Previous, plus single printable characters.</li></ul><p>A screenshot&#39;s <code>path</code> request field is validated as non-empty by the protocol; the executable currently captures and streams the image to the client, <strong>not</strong> a VFS file at that path.</p><h2 id="security-and-failure-boundaries" tabindex="-1">Security and failure boundaries <a class="header-anchor" href="#security-and-failure-boundaries" aria-label="Permalink to &quot;Security and failure boundaries&quot;">​</a></h2><p>The agent accepts input requests over its mounted transport; it does <strong>not</strong> implement a login or authorization check inside <code>dispatch</code>. Restrict access to <code>/devices/debug/transport</code> at the surrounding platform/VFS boundary and do not expose it to untrusted network clients. A service task failure is logged; ordinary input queue contention produces a <code>busy</code> response.</p><h2 id="source-and-api-references" tabindex="-1">Source and API references <a class="header-anchor" href="#source-and-api-references" aria-label="Permalink to &quot;Source and API references&quot;">​</a></h2>`,16)),t("ul",null,[t("li",null,[n(s,{repo:"applications",path:"executables/debug/src/lib.rs"}),e[0]||(e[0]=a(" — executable, service loop, dispatch and framing.",-1))]),t("li",null,[n(s,{path:"libraries/debug_protocol/src/lib.rs"}),e[1]||(e[1]=a(" — request schema and size limits.",-1))]),e[2]||(e[2]=t("li",null,[t("a",{href:"/explanation/architecture/subsystems/graphics.html"},"Graphics subsystem"),a(" — actual capture and injection.")],-1)),e[3]||(e[3]=t("li",null,[t("a",{href:"/explanation/architecture/libraries/executable.html"},"Executable contract"),a(" — task launch and context.")],-1))])])}const f=i(c,[["render",p]]);export{y as __pageData,f as default};
